(()=>{
const root=document.querySelector('#tea-journey'),main=root.querySelector('main'),footer=root.querySelector('footer');
const sections=[['flavor','Flavor & aroma'],['feel','Body & texture'],['energy','Energy'],['storage','Storage']];
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='teajia-tasting-v2-v1';
const fresh={version:1,overall:'',ratings:{},observations:{},values:{},note:'',tea:{name:'Da Hong Pao',teaName:'Da Hong Pao',category:'Rock oolong',style:'Roasted oolong / Wuyi',shop:'Your tea shop · sample tasting',chinese:'',year:'',country:'',region:'',pageNotes:'',lore:'',terroir:'',processing:''},brewing:{},savedAt:null};
let s=structuredClone(fresh);try{const saved=JSON.parse(localStorage.getItem(key));if(saved?.version===1)s={...s,...saved}}catch{}
let workspace='tasting',page='assess',tab='flavor',flavorMode='Aromas',wheelMode='wheel',compact=false,search='',active=null,editFlavor=null,wordMeanings=false,notice='',wheel=null;
const vocab=VOCABULARY;
// Content authority: consolidated sections 1–9. No descriptor computes an appraisal.
// Keep the existing tiles/overlay; explicit absence and amount answers use the shell's optional strips.
vocab.storage=vocab.storage.filter(g=>g.group!=='Effect on other character');
vocab.feel=vocab.feel.filter(g=>!['Body','Coating','Drying','Salivation · Sheng jin'].includes(g.group));
s.tea.style=s.tea.style||'Unknown style';
const startingSets=STARTING_POINTS.styles;
let referenceProfile='',activeSense='aroma',copyMessage='';
const wheelPositions={aroma:null,flavor:null};
function sensoryRecord(name){return s.observations['sensory|'+name]}
function senseDetails(o){return activeSense==='aroma'?(o.aroma||{}):o.flavor}
function migrateSenses(){for(const o of Object.values(s.observations)){if(o.senseVersion||!o.contexts?.includes('flavor'))continue;const where=o.flavor?.where;if(where==='Aroma'||where==='Both'){o.aroma=structuredClone(o.flavor||{});delete o.aroma.where;o.contexts.push('aroma');if(where==='Aroma')o.contexts=o.contexts.filter(c=>c!=='flavor');}o.senseVersion=1;}}
migrateSenses();
const whenValues=o=>Array.isArray(o.flavor.when)?o.flavor.when:o.flavor.when?[o.flavor.when]:[];
const shared=new Set(vocab.semantics.storageFlavorCrossReferences);
function B(label,action,value='',sel=false,cl='',extra=''){return `<button type="button" class="${cl}" data-action="${action}" data-value="${E(value)}" aria-pressed="${sel}" ${extra}>${label}</button>`}
function eligible(){return sections.filter(([id])=>s.ratings[id]!=='Ordinary')}
function persist(dirty=true){if(dirty)s.savedAt=null;try{localStorage.setItem(key,JSON.stringify(s));notice=''}catch{notice='This browser could not keep the draft. Keep this page open.'}status()}
function status(){root.querySelector('#save').textContent=s.savedAt?'Saved':'Save';root.querySelector('#save-status').textContent=notice||(s.savedAt?'Saved in this browser only · not synced to your journal.':'Draft kept in this browser · not synced to your journal.');}
function rating(id){return s.ratings[id]||'Undecided'}
function obsKey(section,group,name){return ['flavor','aroma'].includes(section)||(section==='storage'&&shared.has(name))?'sensory|'+name:[section,group,name].join('|')}
function selected(section,group,name){return s.observations[obsKey(section,group,name)]?.contexts.includes(section)}
function flavorNotes(){return Object.values(s.observations).filter(o=>o.contexts.includes(activeSense)).map(o=>({name:o.name,group:o.group,...senseDetails(o)}))}
function toggleObs(section,group,name,description=''){const k=obsKey(section,group,name),o=s.observations[k];if(o?.contexts.includes(section)){o.contexts=o.contexts.filter(c=>c!==section);if(!o.contexts.length)delete s.observations[k];active=null}else{const target=o||{name,group,description,contexts:[],levels:{},flavor:{}};target.contexts.push(section);s.observations[k]=target;active=['flavor','aroma'].includes(section)||group==='Explicit absence'?null:k;}persist();return k}
function toggleFlavor(name,group){const k=toggleObs(activeSense,group,name,vocab.flavorDefinitions[name]||'A sensory resemblance, in your own words.');if(s.observations[k]){s.observations[k].senseVersion=1;s.observations[k].aroma=s.observations[k].aroma||{};}persist();wheel?.updateNotes(flavorNotes());renderFlavorRecord();}
function contextTitle(){root.querySelector('#tea-title').textContent=s.tea.name||'Unnamed tea';root.querySelector('#tea-context').textContent=(s.tea.category||'Tea')+' · '+(s.tea.shop||'Shop sample')}
function render(){wheel?.destroy();wheel=null;active=active&&s.observations[active]?active:null;contextTitle();root.querySelector('.back-head').hidden=page==='assess'||workspace!=='tasting';root.querySelector('.workspace-nav').innerHTML=[['tasting','Tasting'],['notes','Note'],['study','Study'],['details','Edit tea']].map(([id,n])=>B(n,'workspace',id,workspace===id)).join('');if(workspace==='notes')renderNotes();else if(workspace==='study')renderStudy();else if(workspace==='details')renderDetails();else if(page==='assess')renderAssess();else renderExplore();status()}
function renderAssess(){main.innerHTML=`<div class="overall"><h4>What do you think of this tea?</h4><div class="overall-grid">${[['Exceptional','Among the best'],['Good','Would drink again'],['Average','Nothing stands out'],['Disappointing','Falls short']].map(([n,d])=>B(`${n}<span>${d}</span>`,'overall',n,s.overall===n)).join('')}</div></div><p class="small assessment-hint">Leave unmarked if undecided. Strength and Weakness can both apply.</p>${sections.map(([id,n])=>`<section class="quick"><div class="row"><h3>${n}</h3><span class="small">${rating(id)==='Both'?'Strength + Weakness':rating(id)==='Undecided'?'':''}</span></div><div class="assess">${['Strength','Ordinary','Weakness'].map(v=>B(v,'rate',id+'|'+v,rating(id)===v||(rating(id)==='Both'&&v!=='Ordinary'))).join('')}</div></section>`).join('')}<div class="assess-next">${B('Explore →','explore','',false,'primary',eligible().length?'':'disabled')}<p class="small">${eligible().length?'Explore in any order, or save here.':'All four sections are Ordinary. You can save here.'}</p></div>`;}
function renderExplore(){const list=eligible();if(!list.some(([id])=>id===tab))tab=list[0]?.[0];if(!tab){page='assess';renderAssess();return}main.innerHTML=`<nav class="section-dock" role="tablist" aria-label="Tasting sections">${list.map(([id,n])=>`<button role="tab" id="tab-${id}" aria-controls="tasting-panel" aria-selected="${tab===id}" data-action="tab" data-value="${id}">${id==='flavor'?'Flavor & aroma':n}</button>`).join('')}</nav><section class="chapter" id="tasting-panel" role="tabpanel" aria-labelledby="tab-${tab}"><div class="chapter-lead"><h3>${sections.find(x=>x[0]===tab)[1]}</h3>${rating(tab)==='Undecided'?'':B(rating(tab)==='Both'?'Strength + Weakness':rating(tab),'back','',false,'plain assessment-link')}</div><div id="section-content"></div></section>`;if(tab==='flavor')renderFlavor();else renderObservations(tab)}
function field(k,title,choices){return `<div class="metric"><p>${title}</p><div class="strip">${choices.map(v=>B(v,'value',k+'|'+v,s.values[k]===v)).join('')}</div></div>`}
const intros={feel:'Body, texture, salivation, drying and throat sensations.',energy:'Your subjective response during and after tea · sometimes called cha qi.',storage:'Character you associate with storage. Impressions do not establish history or safety.'};
const groupHelp={'Texture':'Smooth and Rough describe friction; Oily describes slickness.','Coating':'What remains after swallowing; independent of Oily.','Drying & salivation':'Loss of moisture and increased mouth watering can coexist.','Throat comfort':'How swallowing and the feeling afterwards affect your throat.','Local sensations':'Local sensations in the mouth or throat.','Mental clarity':'How clear your thinking feels.','Attention':'How steady your attention feels.','Mood':'How settled or uplifted you feel.','Activation':'How activated or sleepy you feel.','Physical sensations':'Bodily sensations, distinct from mouth and throat feel.','Recognizable character':'One sensory observation, with a storage association.','Other aromas':'Comparisons that do not establish their cause.'};
function showTerm(t,section){const r=rating(section);return r==='Strength'?t.valence!=='negative':r==='Weakness'?t.valence!=='positive':true}
function tile(section,group,t){group=t.originalGroup||group;const absence=group==='Explicit absence';const k=obsKey(section,group,t.name),on=selected(section,group,t.name),o=s.observations[k],open=active===k&&on&&!absence;return `<div class="observation-unit ${on?'observation-selected':''} ${open?'editing-intensity':''} ${t.name.length>22?'wide-term':''}" data-key="${E(k)}"><button class="observation-toggle" data-action="observation" data-value="${E(JSON.stringify([section,group,t.name,t.description]))}" aria-pressed="${!!on}" title="${E(t.description)}"><span>${E(t.name)}</span></button><div class="intensity-slot">${on&&!absence?B(`${E(o.levels[section]||'Intensity')} <span aria-hidden="true">⌄</span>`,'intensityEdit',k,false,'intensity-edit',`aria-label="Edit ${E(t.name)} intensity" aria-expanded="${open}"`):''}</div>${open?`<div class="intensity-popover" role="group" aria-label="${E(t.name)} intensity"><p>${E(t.description)}</p>${['Slight','Moderate','Strong'].map(l=>B(l,'level',k+'~'+l,o.levels[section]===l)).join('')}${section==='feel'?B('Location & duration','feelPrecision',k,false,'precision-link'):''}${B('Remove','remove',k,false,'remove-observation')}</div>`:''}</div>`}
function renderObservations(section){const host=main.querySelector('#section-content');let groups=vocab[section].map(g=>({...g,terms:g.terms.filter(t=>showTerm(t,section))})).filter(g=>g.terms.length);const custom=Object.values(s.observations).filter(o=>o.contexts.includes(section)&&(o.personal||!vocab[section].some(g=>g.terms.some(t=>t.name===o.name&&(g.group===o.group||(section==='storage'&&shared.has(o.name))))))).map(o=>({name:o.name,description:o.description,valence:'neutral',originalGroup:o.group}));if(custom.length)groups.push({group:'Your words',terms:custom});host.innerHTML=`<p class="section-description">${intros[section]}</p>${section==='feel'?field('feel.body','Body · how substantial the liquid feels',['Light','Medium','Full']):''}<div class="row filter-copy"><p class="small">Words to explore</p>${B(wordMeanings?'Hide meanings':'Word meanings','meanings','',wordMeanings,'plain')}</div>${groups.map(g=>`<section class="option-group"><h4>${E(g.group==='Explicit absence'?(section==='energy'?'Change noticed':'Storage character'):g.group)}</h4>${groupHelp[g.group]?`<p class="small group-help">${groupHelp[g.group]}</p>`:''}<div class="observation-grid">${g.terms.map(t=>tile(section,g.group,t)).join('')}</div>${wordMeanings?`<dl class="meanings">${g.terms.map(t=>`<div><dt>${E(t.name)}</dt><dd>${E(t.description)}</dd></div>`).join('')}</dl>`:''}</section>`).join('')}${section==='feel'?feelAttributes():''}${section==='feel'?field('feel.persistence','Persistence · how long the sensation remains',['Brief','Moderate','Lingering'])+field('feel.location','Location of drying / coating · optional',['Mouth','Throat','Both']):''}${customForm(section)}${section==='energy'?`<section class="timing-details"><div class="row"><h4>How it developed</h4><span class="small">Optional</span></div><p class="section-description">One connected experience, across the whole session.</p><div class="timing-fields">${field('energy.onset','When did it start?',['While drinking','After drinking'])}${field('energy.progression','How did it change?',['Stayed steady','Built gradually','Came in waves'])}${field('energy.duration','How long did it last?',['Brief','Sustained','Long-lasting'])}${B('Still feeling it','value','energy.ongoing|Yes',s.values['energy.ongoing']==='Yes')}</div></section>`:section==='storage'?field('storage.masking','Does it obscure the rest of the tea?',['Leaves it clear','Partly masks it','Mostly masks it'].filter(n=>rating('storage')==='Strength'?n==='Leaves it clear':rating('storage')==='Weakness'?n!=='Leaves it clear':true)):''}<div class="retained-summary">${retained(section,groups)}</div>`;}
function retained(section,groups){const visible=new Set(groups.flatMap(g=>g.terms.map(t=>obsKey(section,t.originalGroup||g.group,t.name))));const hidden=Object.entries(s.observations).filter(([k,o])=>o.contexts.includes(section)&&!visible.has(k));return hidden.length?`<p class="small">Kept outside this filter: ${hidden.map(([,o])=>E(o.name)).join(', ')}. Change assessment to see them.</p>`:''}
function feelAttributes(){return `<section class="option-group"><h4>After swallowing</h4><p class="small">Coating is a layer-like sensation that remains; it does not imply Oily.</p>${field('feel.coating','Coating · one optional answer',['Not noticed','Noticeable'])}${field('feel.drying','Drying · mouth or throat feels drier',['Not noticed','Slight','Moderate','Strong'])}${field('feel.salivation','Salivation · Sheng jin · increased mouth watering',['Not noticed','Gentle','Abundant'])}<p class="small">Drying and salivation can coexist. Leaving a choice blank records no answer.</p></section>`}
function openStartingWord(name){if(['Sweet','Bitter','Sour / tart','Umami','Salty'].includes(name)){activeSense='flavor';flavorMode='Basic tastes';renderFlavor();return}const i=TeaWheel.families.findIndex(f=>f.notes.includes(name)||f.name===name||(name==='Earthy'&&f.name==='Earth & fungi')||(name==='Mineral-like'&&f.name==='Stone & metal'));if(i<0)return;flavorMode='Aromas';wheelMode='wheel';renderFlavor();wheel?.navigate(i)}
function styleSuggestions(){const style=s.tea.style,words=startingSets[style]||(style==='Oolong · unspecified'?['Floral','Fresh fruit','Nuts & grain','Roast & cocoa','Vegetal']:[]),profiles=REFERENCE_PROFILES.demo_teas.filter(p=>p.expert),profile=profiles.find(p=>p.id===referenceProfile);return `<section class="style-suggestions"><h4>${words.length?E(style)+' · starting words':'Explore without a style reference'}</h4><p class="small">Editorial suggestions from the recorded style. Opening a word records nothing.</p>${words.length?`<div class="words">${words.map(n=>B(E(n),'suggest',n)).join('')}</div>`:'<p class="small">No style assumed. All flavor families remain available.</p>'}<label class="small reference-label" for="reference-profile">Sourced reference comparison · optional</label><select id="reference-profile"><option value="">No reference comparison</option>${profiles.map(p=>`<option value="${p.id}" ${referenceProfile===p.id?'selected':''}>${E(p.name)}</option>`).join('')}</select>${profile?`<div class="reference-example"><h4>${E(profile.name)}</h4><p class="small">${E(profile.classification||profile.style)} · Adapted source vocabulary, not your tasting.</p><div class="words">${profile.expert.map(n=>B(E(n),'suggest',n)).join('')}</div><p class="small"><a href="${E(REFERENCE_PROFILES.expert_source.url)}" target="_blank" rel="noopener">Taiwan specialty-tea study</a> · ${E(REFERENCE_PROFILES.expert_source.scope)} Source attribution preserved; not independently revalidated here.</p></div>`:''}</section>`}
function customForm(section){return `<form class="custom-form" data-section="${section}"><label for="custom-${section}" class="small">Use your own words</label><div><input id="custom-${section}" name="term" placeholder="A personal description…" maxlength="120" required><button type="submit">Add</button></div></form>`}
function renderFlavor(){const host=main.querySelector('#section-content');host.innerHTML=`<div class="sense-switch" aria-label="Aroma or flavor">${B('Aroma','sense','aroma',activeSense==='aroma')}${B('Flavor','sense','flavor',activeSense==='flavor')}</div><p class="section-description">${activeSense==='aroma'?'What you smell. Aroma selections stay separate from the sip.':'What you experience in the sip. Flavor selections stay separate from aroma.'}</p><div class="copy-row">${B('Copy aroma notes to flavor','copyAroma','',false,'plain',Object.values(s.observations).some(o=>o.contexts.includes('aroma'))?'':'disabled')}<span class="small" role="status">${E(copyMessage)}</span></div><input id="flavor-search" class="search" aria-label="Find a ${activeSense} note or use your own word" placeholder="Find a ${activeSense} note…" value="${E(search)}">${activeSense==='flavor'?`<nav class="flavor-categories" aria-label="Flavor groups">${['Aromas','Basic tastes','Expression','Finish'].map(n=>B(n==='Aromas'?'Notes':n,'flavorMode',n,flavorMode===n)).join('')}</nav>`:''}<div id="flavor-library"></div><section id="flavor-record"></section><div id="flavor-detail"></div>`;renderFlavorLibrary();renderFlavorRecord()}
function flavorWord(name,group){return B(E(name),'flavorToggle',JSON.stringify([name,group]),!!selected(activeSense,group,name),'flavor-word',`title="${E(vocab.flavorDefinitions[name]||'Resembles '+name.toLowerCase()+'.')}"`)}
function renderFlavorLibrary(){wheel?.destroy();wheel=null;const lib=main.querySelector('#flavor-library'),families=TeaWheel.families;
if(search.trim()){const q=search.trim().toLowerCase(),all=families.flatMap(f=>[{name:(f.name==='Earth & fungi'?'Earthy':f.name==='Stone & metal'?'Mineral-like':f.name),group:f.name},...f.notes.map(name=>({name,group:f.name}))]).concat((activeSense==='flavor'?['Sweet','Bitter','Sour / tart','Umami','Salty']:[]).map(name=>({name,group:'Basic tastes'}))),found=all.filter(t=>(t.name+' '+(t.name==='Umami'?'savory':'')+' '+(t.name==='Drying'?'astringency astringent':'')).toLowerCase().includes(q));lib.innerHTML=`<section class="block"><h4>Matching words</h4><div class="words">${found.map(t=>flavorWord(t.name,t.group)).join('')}</div>${B('Use “'+E(search.trim())+'”','customFlavor',search.trim())}<p class="small">Your words are kept exactly as entered.</p></section>`;return}
if(flavorMode==='Aromas'){lib.innerHTML=`<div class="row wheel-tools"><div class="browser-mode">${B('Wheel','wheelMode','wheel',wheelMode==='wheel')}${B('Words','wheelMode','words',wheelMode==='words')}</div>${wheelMode==='wheel'?B('Compact','compact','',compact,'plain'):''}</div>${wheelMode==='wheel'?'<div id="wheel-host"></div>':families.map(f=>`<div class="option-group"><h4>${E(f.name)}</h4><p class="small">${E(f.description)}</p><div class="words">${[(f.name==='Earth & fungi'?'Earthy':f.name==='Stone & metal'?'Mineral-like':f.name),...f.notes].map(n=>flavorWord(n,f.name)).join('')}</div></div>`).join('')}${styleSuggestions()}`;if(wheelMode==='wheel')wheel=TeaWheel.mount(lib.querySelector('#wheel-host'),{notes:flavorNotes(),compact,onToggle:toggleFlavor,onEdit:openFlavorDetail,onNavigate:name=>{wheelPositions[activeSense]=name;}});if(wheel&&wheelPositions[activeSense]!==null)wheel.navigate(wheelPositions[activeSense]);}
else if(flavorMode==='Basic tastes')lib.innerHTML=`<div class="option-group"><p class="small">Tastes in the sip, distinct from aromatic comparisons. Bitterness can be welcome.</p><div class="words">${['Sweet','Bitter','Sour / tart','Umami','Salty'].map(n=>flavorWord(n,'Basic tastes')).join('')}</div></div>`;
else if(flavorMode==='Expression'){const r=rating('flavor');lib.innerHTML=[['Can I make out the notes?',['Distinct','Hard to distinguish']],['How much is happening?',['Several layers','One main character']],['Do the flavors fit together?',['Work together','Clash']]].map(([q,opts],i)=>field('flavor.expression'+i,q+['<span class="field-help">Whether individual impressions are recognizable.</span>','<span class="field-help">Several impressions or one dominant character; neither is inherently better.</span>','<span class="field-help">Whether the flavors fit harmoniously or conflict.</span>'][i],opts.filter(n=>r==='Strength'?!['Hard to distinguish','Clash'].includes(n):r==='Weakness'?!['Distinct','Work together'].includes(n):true))).join('');}
else lib.innerHTML=`<div class="option-group"><h4>Returning sweetness · Hui gan</h4><p class="small">Sweetness appears or becomes clearer after swallowing. Different from sweetness that simply remains.</p>${field('flavor.huigan','What did you notice?',['Not noticed','Subtle','Moderate','Pronounced'])}${s.values['flavor.huigan']==='Returning sweetness'?'<p class="small">Kept from earlier draft: Returning sweetness · intensity unspecified.</p>':''}<h4>Aftertaste</h4><p class="small">A taste or aroma remains. Select an existing word and set its timing to Aftertaste.</p>${field('flavor.aftertasteDuration','Aftertaste duration · optional',['Brief','Moderate','Lingering'])}${B('Choose an aftertaste word','aftertaste')}</div>`;
}
function renderFlavorRecord(){const target=main.querySelector('#flavor-record');if(!target)return;const notes=flavorNotes();target.innerHTML=`<div class="row"><h4>Your ${activeSense} notes</h4><span class="small">${notes.length?notes.length+' recorded':''}</span></div>${notes.length?`<div class="words recorded">${notes.map(n=>B(`${E(n.name)}${[n.where,n.intensity,n.when,n.duration].filter(Boolean).length?`<small>${E([n.where,n.intensity,n.when,n.duration].filter(Boolean).map(v=>Array.isArray(v)?v.join(' + '):v).join(' · '))}</small>`:''}`,'flavorEdit',n.name,false)).join('')}</div>`:`<p class="small">No ${activeSense} notes yet. Choose a family or a specific note.</p>`}`;const copy=root.querySelector('[data-action=copyAroma]');if(copy)copy.disabled=!Object.values(s.observations).some(o=>o.contexts.includes('aroma'));if(editFlavor)renderFlavorDetail()}
function openFlavorDetail(name){editFlavor=name;renderFlavorDetail();main.querySelector('#flavor-detail')?.scrollIntoView({block:'nearest',behavior:'smooth'})}
function renderFlavorDetail(){const target=main.querySelector('#flavor-detail'),o=sensoryRecord(editFlavor);if(!target)return;if(!o?.contexts.includes(activeSense)){target.innerHTML='';return}const d=senseDetails(o),times=Array.isArray(d.when)?d.when:d.when?[d.when]:[];target.innerHTML=`<section class="flavor-editor"><div class="row"><h4>${E(o.name)} · ${activeSense}</h4>${B('Done','detailDone','',false,'plain')}</div><p class="small">${E(vocab.flavorDefinitions[o.name]||o.description||'A sensory resemblance, in your own words.')}</p>${[['intensity','Intensity',['Subtle','Moderate','Pronounced']],['when','When noticed · choose all that apply',activeSense==='aroma'?['Early','Middle','Late']:['Early','Middle','Late','Aftertaste']],...(activeSense==='flavor'&&times.includes('Aftertaste')?[['duration','Aftertaste duration',['Brief','Moderate','Lingering']]]:[])].map(([k,label,opts])=>`<div class="metric"><p>${label}</p><div class="strip">${opts.map(v=>B(v,'flavorValue',k+'|'+v,k==='when'?times.includes(v):d[k]===v)).join('')}</div></div>`).join('')}<label class="small" for="flavor-comment">Your words</label><textarea id="flavor-comment">${E(d.comment||'')}</textarea>${B('Remove '+activeSense+' note','flavorRemove',o.name,false,'plain')}<p class="small">Each detail is optional. Tap it again to clear.</p></section>`}
function renderPrecision(k){const o=s.observations[k];if(!o)return;let panel=main.querySelector('#feel-precision');if(!panel){panel=document.createElement('section');panel.id='feel-precision';panel.className='block';main.querySelector('#section-content').append(panel)}panel.innerHTML=`<div class="row"><h4>${E(o.name)} · details</h4>${B('Close','precisionClose','',false,'plain')}</div><p class="small">Optional details for this sensation. Tap an answer again to clear.</p>${[['location','Where?',['Mouth','Throat','Both']],['persistence','How long does it remain?',['Brief','Moderate','Lingering']]].map(([f,q,choices])=>`<div class="metric"><p>${q}</p><div class="strip">${choices.map(c=>B(c,'precisionValue',JSON.stringify([k,f,c]),o.precision?.[f]===c)).join('')}</div></div>`).join('')}`;panel.scrollIntoView({block:'nearest'})}
function renderStudy(){main.innerHTML=`<section class="block"><h3>Whole-session study</h3><p class="section-description">Optional observations about the whole tea, separate from individual sections and brewing style.</p>${field('study.endurance','Endurance · how its satisfying presence holds',['Fades early','Holds across infusions','Still going when I stopped'])}${field('study.development','Development · how the tea changes across infusions',['Opens gradually','Changes distinctly','Stays steady','Peaks then fades'])}${field('study.coherence','Coherence · how aroma, taste and feel fit together',['Integrated','Uneven','Disjointed'])}<h4 class="brewing-title">Session context</h4><p class="small">Context for comparison, never a quality score.</p><div class="tea-fields">${[['dose','Leaf dose','e.g. 5 g'],['volume','Vessel volume','e.g. 100 ml'],['water','Water','Source or description'],['timing','Infusion timing','Your timings'],['infusions','Infusions tasted','Number or range'],['startingState','Starting state','How you felt before'],['food','Food','Optional context'],['otherCaffeine','Other caffeine','Optional context']].map(([k,l,h])=>`<label>${l}<input data-brewing="${k}" value="${E(s.brewing[k])}" placeholder="${h}"></label>`).join('')}</div><p class="small">Temperature and vessel remain in Edit tea.</p></section>`}
function renderNotes(){main.innerHTML=`<section class="block"><div class="row"><h3>Note to myself</h3>${B('Voice note','voice','',false,'voice-note')}</div><textarea id="private-note" aria-label="Private note" placeholder="A thought, comparison, or question to revisit…">${E(s.note)}</textarea><p class="small" id="voice-status" role="status">Private to this local prototype.</p></section>`;}
function renderDetails(){const fields=[['name','Name shown'],['teaName','Tea name'],['shop','Shop / sample context'],['chinese','Chinese'],['category','Type'],['year','Year'],['country','Country'],['region','Region'],['pageNotes','Notes on the page'],['lore','Lore'],['terroir','Terroir'],['processing','Processing']];main.innerHTML=`<section class="block"><h3>Tea details</h3><div class="tea-fields">${fields.map(([k,label])=>`<label>${label}${['pageNotes','lore','terroir','processing'].includes(k)?`<textarea data-tea="${k}">${E(s.tea[k])}</textarea>`:`<input data-tea="${k}" value="${E(s.tea[k])}">`}</label>`).join('')}<label>Recorded tea style<select data-tea="style" aria-label="Recorded tea style">${['Unknown style','Oolong · unspecified',...Object.keys(startingSets)].map(n=>`<option value="${E(n)}" ${s.tea.style===n?'selected':''}>${E(n)}</option>`).join('')}</select></label></div><h3 class="brewing-title">Brewing context</h3><p class="small">Session details, separate from tea quality.</p><div class="tea-fields"><label>Water temperature<input data-brewing="temperature" value="${E(s.brewing.temperature)}" placeholder="e.g. 95 °C"></label><label>Pot / vessel<input data-brewing="vessel" value="${E(s.brewing.vessel)}" placeholder="Your brewing vessel"></label></div></section>`}
root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,v=el.dataset.value;
if(a==='save'){s.savedAt=new Date().toISOString();persist(false);return}
if(a==='voice'){main.querySelector('#voice-status').textContent='Voice note is a preview control. This prototype does not record audio.';return}
if(a==='workspace'){workspace=v;active=null;render();return}
if(a==='back'){page='assess';active=null;render();return}
if(a==='explore'){page='explore';render();return}
if(a==='tab'){tab=v;active=null;editFlavor=null;search='';render();return}
if(a==='overall'){s.overall=s.overall===v?'':v;persist();render();return}
if(a==='rate'){const[id,r]=v.split('|'),old=rating(id);if(r==='Ordinary'){if(old===r)delete s.ratings[id];else s.ratings[id]=r}else if(old==='Both')s.ratings[id]=r==='Strength'?'Weakness':'Strength';else if(old===r)delete s.ratings[id];else s.ratings[id]=['Strength','Weakness'].includes(old)?'Both':r;persist();render();return}
if(a==='observation'){const[section,group,name,description]=JSON.parse(v);toggleObs(section,group,name,description);renderObservations(tab);return}
if(a==='feelPrecision'){active=null;renderObservations(tab);renderPrecision(v);return}
if(a==='precisionClose'){renderObservations(tab);return}
if(a==='precisionValue'){const[k,f,c]=JSON.parse(v);const o=s.observations[k];o.precision=o.precision||{};o.precision[f]=o.precision[f]===c?null:c;persist();renderPrecision(k);return}
if(a==='intensityEdit'){active=active===v?null:v;renderObservations(tab);return}
if(a==='level'){const[k,l]=v.split('~'),o=s.observations[k];o.levels[tab]=o.levels[tab]===l?null:l;active=null;persist();renderObservations(tab);return}
if(a==='remove'){const o=s.observations[v];o.contexts=o.contexts.filter(c=>c!==tab);if(!o.contexts.length)delete s.observations[v];active=null;persist();renderObservations(tab);return}
if(a==='meanings'){wordMeanings=!wordMeanings;renderObservations(tab);return}
if(a==='feelAttribute'){const[k,choice]=v.split('|');s.values[k]=s.values[k]===choice?null:choice;persist();renderObservations(tab);return}
if(a==='value'){const[k,choice]=v.split('|');s.values[k]=s.values[k]===choice?null:choice;persist();workspace==='study'?renderStudy():tab==='flavor'?renderFlavorLibrary():renderObservations(tab);return}
if(a==='sense'){activeSense=v;flavorMode='Aromas';search='';editFlavor=null;copyMessage='';renderFlavor();return}
if(a==='copyAroma'){let count=0;for(const o of Object.values(s.observations)){if(o.contexts.includes('aroma')&&!o.contexts.includes('flavor')){o.contexts.push('flavor');o.flavor={};o.senseVersion=1;count++;}}copyMessage=count?`${count} note${count===1?'':'s'} copied · details stay separate.`:'All aroma notes are already in Flavor.';activeSense='flavor';flavorMode='Aromas';search='';editFlavor=null;persist();renderFlavor();return}
if(a==='flavorMode'){flavorMode=v;search='';main.querySelector('#flavor-search').value='';renderFlavor();return}
if(a==='wheelMode'){wheelMode=v;renderFlavorLibrary();return}
if(a==='compact'){compact=!compact;renderFlavorLibrary();return}
if(a==='flavorToggle'){const[n,g]=JSON.parse(v);toggleFlavor(n,g);renderFlavorLibrary();return}
if(a==='customFlavor'){toggleFlavor(v,'Your words');search='';main.querySelector('#flavor-search').value='';renderFlavorLibrary();return}
if(a==='suggest'){openStartingWord(v);return}
if(a==='flavorEdit'){openFlavorDetail(v);return}
if(a==='detailDone'){editFlavor=null;main.querySelector('#flavor-detail').innerHTML='';return}
if(a==='flavorValue'){const[k,choice]=v.split('|'),o=sensoryRecord(editFlavor);o.aroma=o.aroma||{};const d=senseDetails(o);if(k==='when'){const old=Array.isArray(d.when)?d.when:d.when?[d.when]:[];d.when=old.includes(choice)?old.filter(x=>x!==choice):[...old,choice]}else d[k]=d[k]===choice?null:choice;persist();renderFlavorRecord();return}
if(a==='flavorRemove'){toggleObs(activeSense,'',v);editFlavor=null;renderFlavor();return}
if(a==='aftertaste'){flavorMode='Aromas';wheelMode='words';renderFlavor();return}
});
root.addEventListener('change',e=>{if(e.target.id==='reference-profile'){referenceProfile=e.target.value;renderFlavorLibrary()}if(e.target.dataset.tea==='style'){s.tea.style=e.target.value;persist()}});
root.addEventListener('input',e=>{const t=e.target;if(t.id==='private-note'){s.note=t.value;persist()}else if(t.dataset.tea){s.tea[t.dataset.tea]=t.value;contextTitle();persist()}else if(t.dataset.brewing){s.brewing[t.dataset.brewing]=t.value;persist()}else if(t.id==='flavor-search'){search=t.value;renderFlavorLibrary()}else if(t.id==='flavor-comment'){senseDetails(sensoryRecord(editFlavor)).comment=t.value;persist()}});
root.addEventListener('submit',e=>{if(!e.target.matches('.custom-form'))return;e.preventDefault();const section=e.target.dataset.section,name=new FormData(e.target).get('term').trim();if(!name)return;const k=toggleObs(section,'Your words',name,'Your personal description, preserved as entered.');if(s.observations[k])s.observations[k].personal=true;persist();renderObservations(section)});
document.addEventListener('click',e=>{if(active&&e.target.isConnected&&!e.target.closest('.editing-intensity')){active=null;if(workspace==='tasting'&&page==='explore'&&tab!=='flavor')renderObservations(tab)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){active=null;renderObservations(tab)}const t=e.target.closest('[role=tab]');if(t&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const ids=eligible().map(x=>x[0]),i=ids.indexOf(tab);tab=ids[e.key==='Home'?0:e.key==='End'?ids.length-1:(i+(e.key==='ArrowRight'?1:-1)+ids.length)%ids.length];render();main.querySelector('#tab-'+tab).focus()}});
function layoutTiles(){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');main.querySelectorAll('.observation-grid').forEach(grid=>{const units=[...grid.children],w=grid.clientWidth;let index=0,row=1;while(index<units.length){let count=Math.min(4,units.length-index);for(;count>1;count--){const width=(w-(count-1)*6)/count;if(units.slice(index,index+count).every(u=>{const label=u.querySelector('.observation-toggle');ctx.font=getComputedStyle(label).font;return ctx.measureText(label.textContent.trim()).width+22<=width&&width>=82}))break;}units.slice(index,index+count).forEach((u,i)=>{u.style.gridColumn=`${i*(12/count)+1} / span ${12/count}`;u.style.gridRow=row;});index+=count;row++;}})}
new MutationObserver(()=>requestAnimationFrame(layoutTiles)).observe(main,{childList:true,subtree:true});window.addEventListener('resize',layoutTiles);
render();
})();
